def build_agent(sandbox):
    # Create the main hull with optimized density for buoyancy and mass
    hull = sandbox.add_beam(x=5.0, y=1.5, width=2.0, height=1.0, density=250.0)

    # Add paddles for propulsion with appropriate dimensions
    # Paddle 1: Left side
    paddle1 = sandbox.add_beam(x=5.0 - 0.5, y=1.5, width=0.15, height=1.0, density=250.0)
    joint1 = sandbox.add_joint(hull, paddle1, anchor_point=(5.0 - 0.5, 1.5), type='rigid')

    # Paddle 2: Right side
    paddle2 = sandbox.add_beam(x=5.0 + 0.5, y=1.5, width=0.15, height=1.0, density=250.0)
    joint2 = sandbox.add_joint(hull, paddle2, anchor_point=(5.0 + 0.5, 1.5), type='rigid')

    return hull, [paddle1, paddle2]

